const html = require('fs').readFileSync('gvom.html','utf8');
function extract(id) {
  const marker = 'id=\"'+id+'\"';
  const idx = html.indexOf(marker);
  if (idx === -1) { console.log('NOT FOUND', id); return; }
  // find start of the tag
  let start = html.lastIndexOf('<', idx);
  console.log('=== '+id+' starts at '+start+' ===');
}
['shopify-section-header','shopify-section-announcement','shopify-section-index-slideshow','shopify-section-index-video','shopify-section-index-collection','shopify-section-index-collection-grid','shopify-section-index-logos','shopify-section-1609344468ab5369dc','shopify-section-index-double','shopify-section-index-map','shopify-section-index-blog','shopify-section-footer'].forEach(extract);
"

