const nodes = data.nodes.filter(n => n.id && n.id.startsWith('shopify-section-'));
nodes.sort((a,b)=>a.rendered.top-b.rendered.top);
for (const n of nodes) console.log(n.id, 'top=',n.rendered.top, 'h=',n.rendered.height);
"

