// Desktop "Shop" dropdown (click/hover via JS so it never sticks open from automated cursor placement)
(function(){
  const wrap = document.querySelector('.has-dropdown');
  if (!wrap) return;
  let hideTimer;
  const open = () => { clearTimeout(hideTimer); wrap.classList.add('open'); };
  const close = () => { hideTimer = setTimeout(()=> wrap.classList.remove('open'), 150); };
  wrap.addEventListener('mouseenter', open);
  wrap.addEventListener('mouseleave', close);
  wrap.querySelector('a').addEventListener('click', (e)=>{ e.preventDefault(); wrap.classList.toggle('open'); });
})();

// Mobile drawer

