const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({ headless: 'new', args: ['--autoplay-policy=no-user-gesture-required'] });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 900 });

  const consoleMsgs = [];
  page.on('console', msg => consoleMsgs.push(`[console.${msg.type()}] ${msg.text()}`));
  page.on('pageerror', err => consoleMsgs.push(`[pageerror] ${err.message}`));
  page.on('requestfailed', req => consoleMsgs.push(`[requestfailed] ${req.url()} ${req.failure()?.errorText}`));
  page.on('response', res => {
    if (res.url().includes('youtube.com/embed') && res.status() >= 400) {
      consoleMsgs.push(`[http ${res.status()}] ${res.url()}`);
    }
  });

  await page.goto('file:///Users/cameron/gumshoe-golden-set/good-vibes/index.html', { waitUntil: 'networkidle2', timeout: 30000 });

  // Scroll to the video hero section
  await page.evaluate(() => {
    const sections = Array.from(document.querySelectorAll('main section'));
    const videoSection = sections.find(s => s.querySelector('#play-video-btn'));
    if (videoSection) videoSection.scrollIntoView();
  });

  // Give the YouTube iframe time to load and start playing
  await new Promise(r => setTimeout(r, 6000));

  // Check the iframe's state
  const frames = page.frames();
  const ytFrame = frames.find(f => f.url().includes('youtube.com/embed'));
  console.log('YouTube iframe found:', !!ytFrame);
  if (ytFrame) {
    console.log('YouTube iframe URL:', ytFrame.url());
    try {
      const bodyText = await ytFrame.evaluate(() => document.body ? document.body.innerText.slice(0, 300) : 'NO BODY');
      console.log('YouTube iframe body text snippet:', JSON.stringify(bodyText));
      const hasVideoTag = await ytFrame.evaluate(() => !!document.querySelector('video'));
      console.log('Has <video> tag inside iframe:', hasVideoTag);
      if (hasVideoTag) {
        const videoState = await ytFrame.evaluate(() => {
          const v = document.querySelector('video');
          return { paused: v.paused, currentTime: v.currentTime, readyState: v.readyState, muted: v.muted, error: v.error ? v.error.code : null };
        });
        console.log('Video element state:', JSON.stringify(videoState));
      }
    } catch (e) {
      console.log('Error inspecting iframe contents (likely cross-origin):', e.message);
    }
  }

  await page.screenshot({ path: '/tmp/video_section_live.png' });
  console.log('--- Console/network messages ---');
  console.log(consoleMsgs.filter(m => m.toLowerCase().includes('youtube') || m.startsWith('[pageerror]') || m.startsWith('[requestfailed]') || m.startsWith('[http')).join('\n') || '(none matching filter)');

  await browser.close();
})();

