const puppeteer = require('puppeteer');

(async () => {
  const browser = await puppeteer.launch({ headless: 'new' });
  const page = await browser.newPage();
  await page.setViewport({ width: 1280, height: 900 });
  await page.goto('file:///Users/cameron/gumshoe-golden-set/good-vibes/index.html', { waitUntil: 'networkidle2', timeout: 30000 });

  const shopLink = await page.$('.has-dropdown a');
  const box = await shopLink.boundingBox();
  await page.mouse.move(box.x + box.width / 2, box.y + box.height / 2);
  await new Promise(r => setTimeout(r, 500));

  const panelBox = await page.evaluate(() => {
    const el = document.querySelector('.dropdown-panel');
    const r = el.getBoundingClientRect();
    return { left: r.left, right: r.right, width: r.width, windowWidth: window.innerWidth };
  });
  console.log('dropdown panel box:', JSON.stringify(panelBox));

  await page.screenshot({ path: '/tmp/megamenu_check.png' });
  await browser.close();
})();

